  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "keep",
  "supportive_card_ids": ["C07","C11","C17","C02","C09","C18","C29","C03","C06","C16","C20","C25","C26","C19","C30","C52","C47"],
  "contradictory_card_ids": ["C55","C60","C57","C58","C61","C59"],
  "prediction_basis_card_ids": ["C07","C11","C17","C02","C09","C18","C03","C19","C52"],
  "claims": [
    {
      "claim": "The closest measured oral-bioavailability contexts for polar 2-halogenated adenine nucleosides are cladribine (absolute F 36–46% in fasted patients) and didanosine (F 22–28% fasted), both clearly above the 20% threshold.",
      "card_ids": ["C07","C11","C17","C02","C09"]
    },
    {
      "claim": "Other small nucleoside analog contexts (zalcitabine, lamivudine, emtricitabine) show absolute F values of 30–93%, supporting meaningful oral absorption for this class.",
      "card_ids": ["C18","C29","C03","C06","C16","C20","C25","C26","C19","C30"]
    },
    {
      "claim": "L4 provides high gastric solubility for the closely related 2-fluoroadenosine and measurable intestinal flux for 3TC, supporting absorption potential for the query's 2-fluoroadenine nucleoside scaffold.",
      "card_ids": ["C52","C47"]
    },
    {
      "claim": "L5 low Caco-2 permeability and efflux records for other nucleosides (EFdA, tenofovir, GS-441524) are mechanistic absorption-limitation signals, but they are not direct F measurements for the query and do not affirmatively establish F < 20%; didanosine, which has secretory efflux, still has F 22–28%.",
      "card_ids": ["C55","C60","C57","C58","C61","C59","C56","C66","C02","C09"]
    },
    {
      "claim": "No affirmative threshold-relevant evidence supports F < 20% for the query; low paliperidone outcomes arise from a different structural class and modified-release formulation and are not transferable.",
      "card_ids": ["C01","C21","C27","C28"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C55","C60","C57","C58","C61","C63","C59","C62","C56","C66","C64","C65"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the exact query molecule.",
    "The query's pyranose sugar differs from the furanose sugars in cladribine, didanosine, and EFdA; transporter recognition and absorption are unmeasured.",
    "No fed/fasted condition, dose, formulation, or species information is available for the query.",
    "No first-pass metabolism or clearance data are available for the query.",
    "L5 permeability/efflux records are for other molecules, not the query, and are not direct systemic-F outcomes."
  ],
  "decision_summary": "The query is a polar 2-fluoroadenine pyranose nucleoside. Direct F measurements for the closest structural contexts (cladribine 36–46%, didanosine 22–28%) and other nucleoside analogs all exceed 20%. L5 adds low Caco-2 permeability and efflux signals for other nucleosides, but these are mechanistic only and do not affirmatively establish F < 20%; didanosine with secretory efflux still has F above threshold. Therefore the prediction remains high with moderate confidence."
}

